CREATE TABLE shipping_methods (code VARCHAR(32) PRIMARY KEY, display_name VARCHAR(120) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, provider VARCHAR(80) NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE shipping_quotes (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL, method VARCHAR(32) NOT NULL, amount_minor BIGINT NOT NULL, currency CHAR(3) NOT NULL, request_hash CHAR(64) NOT NULL, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX shipping_quotes_expiry_idx ON shipping_quotes(expires_at);
CREATE TABLE shipments (id VARCHAR(64) PRIMARY KEY, order_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, provider VARCHAR(80) NOT NULL, provider_shipment_id VARCHAR(160), status VARCHAR(32) NOT NULL, method VARCHAR(32) NOT NULL, tracking_number VARCHAR(160), carrier VARCHAR(120), amount_minor BIGINT NOT NULL, currency CHAR(3) NOT NULL, idempotency_key VARCHAR(160) NOT NULL, request_hash CHAR(64) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(order_id), UNIQUE(provider,provider_shipment_id), UNIQUE(user_id,idempotency_key));
CREATE TABLE shipment_addresses (shipment_id VARCHAR(64) PRIMARY KEY REFERENCES shipments(id) ON DELETE CASCADE, address_json JSONB NOT NULL);
CREATE TABLE shipment_items (shipment_id VARCHAR(64) REFERENCES shipments(id) ON DELETE CASCADE, variant_id VARCHAR(64) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), PRIMARY KEY(shipment_id,variant_id));
CREATE TABLE shipment_tracking_events (id VARCHAR(64) PRIMARY KEY, shipment_id VARCHAR(64) NOT NULL REFERENCES shipments(id), status VARCHAR(32) NOT NULL, provider_event_id VARCHAR(200), payload_json JSONB NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, UNIQUE(provider_event_id));
CREATE TABLE return_shipments (id VARCHAR(64) PRIMARY KEY, shipment_id VARCHAR(64) NOT NULL REFERENCES shipments(id), status VARCHAR(32) NOT NULL, provider_shipment_id VARCHAR(160), created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE shipping_inbox_events(event_id VARCHAR(160) PRIMARY KEY,received_at TIMESTAMPTZ NOT NULL);
CREATE TABLE shipping_outbox_events(id VARCHAR(64) PRIMARY KEY,aggregate_id VARCHAR(64) NOT NULL,event_type VARCHAR(100) NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,occurred_at TIMESTAMPTZ NOT NULL,correlation_id VARCHAR(160) NOT NULL,payload_json JSONB NOT NULL,published_at TIMESTAMPTZ);
CREATE INDEX shipping_outbox_unpublished_idx ON shipping_outbox_events(published_at,occurred_at) WHERE published_at IS NULL;
